package main

import "fmt"

type Base struct {
	ID int
}

func (b Base) Describe() string {
	return fmt.Sprintf("base-%d", b.ID)
}

type Item struct {
	Base
	Name  string `json:"name"`
	Price int
}

func (i *Item) Discount(rate int) {
	i.Price -= i.Price * rate / 100
}

func NewItem(id int, name string, price int) *Item {
	return &Item{Base: Base{ID: id}, Name: name, Price: price}
}

func main() {
	item := NewItem(1, "键盘", 200)
	fmt.Println(item.Describe(), item.Name)

	item.Discount(10)
	fmt.Println(item.Price)

	other := NewItem(1, "键盘", 180)
	fmt.Println(*item == *other)
}
